package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.distribution.TDistribution;

/** Observed-variable linear path analysis with hierarchical exogenous interactions. */
public final class PathProcess {
    private PathProcess(){}
    public enum Metric {UNSTANDARDIZED,MEAN_CENTERED,STANDARDIZED}
    public record Path(int source,int target,int[] moderators){
        public Path{moderators=moderators.clone();Arrays.sort(moderators);if(source<0||target<0||source==target||moderators.length>2)throw new IllegalArgumentException("A process path needs distinct variables and at most two exogenous moderators.");for(int j=0;j<moderators.length;j++)if(moderators[j]<0||moderators[j]==source||moderators[j]==target||j>0&&moderators[j]==moderators[j-1])throw new IllegalArgumentException("Process moderators must be distinct from path endpoints.");}
        public Path(int source,int target){this(source,target,new int[0]);}@Override public int[] moderators(){return moderators.clone();}
    }
    public record Model(int source,int target,List<Path> paths,int[] controls){public Model{paths=List.copyOf(paths);controls=controls.clone();if(source<0||target<0||source==target)throw new IllegalArgumentException("Choose distinct focal source and outcome.");}@Override public int[] controls(){return controls.clone();}}
    public record Options(Metric metric,RobustRegression.Covariance covariance,double confidence,boolean considerControls){public Options{Objects.requireNonNull(metric);Objects.requireNonNull(covariance);Inference.confidence(confidence);}public static Options defaults(){return new Options(Metric.UNSTANDARDIZED,RobustRegression.Covariance.CLASSICAL,.95,true);}}
    /** Probe conditions are in original data units, even for standardized estimation. */
    public record Probe(String name,Map<Integer,Double> values){public Probe{if(name==null||name.isBlank())throw new IllegalArgumentException("Name each process probe.");values=Collections.unmodifiableMap(new LinkedHashMap<>(values));for(var entry:values.entrySet())if(entry.getKey()<0||entry.getValue()==null||!Double.isFinite(entry.getValue()))throw new IllegalArgumentException("Probe values must be finite original-unit moderator values.");}}
    public record Monomial(int[] columns){public Monomial{columns=columns.clone();}@Override public int[] columns(){return columns.clone();}}
    public record Equation(int response,List<Monomial> predictors,OlsRegression.Fit ordinary,RobustRegression.Fit inference){public Equation{predictors=List.copyOf(predictors);}}
    public record ConditionalPath(String probe,int source,int target,Inference.Term inference){}
    public record Effect(String probe,String family,String label,double value){}
    public record Fit(Model model,Options options,int observations,List<String> names,double[] means,double[] centers,double[] scales,List<Probe> probes,List<Equation> equations,List<ConditionalPath> conditionalPaths,List<Effect> effects,List<String> warnings){
        public Fit{names=List.copyOf(names);means=means.clone();centers=centers.clone();scales=scales.clone();probes=List.copyOf(probes);equations=List.copyOf(equations);conditionalPaths=List.copyOf(conditionalPaths);effects=List.copyOf(effects);warnings=List.copyOf(warnings);}@Override public double[] means(){return means.clone();}@Override public double[] centers(){return centers.clone();}@Override public double[] scales(){return scales.clone();}
    }
    public record BootstrapResult(Fit point,Bootstrap.Result inference){}
    private record Definition(int response,List<Monomial> predictors){}
    private record State(double[] means,double[] centers,double[] scales,List<Equation> equations,List<Probe> probes,List<ConditionalPath> paths,List<Effect> effects){}
    static final class Work {
        final Model model;final Options options;final List<String> names;final List<Definition> definitions;final List<List<Path>> routes=new ArrayList<>();final TreeSet<Integer> used=new TreeSet<>(),moderators=new TreeSet<>();final List<Probe> probes;final int width;
        Work(int width,List<String> suppliedNames,Model model,Options options,List<Probe> suppliedProbes){
            this.width=width;this.names=List.copyOf(suppliedNames);this.model=model;this.options=options;if(names.size()!=width||new HashSet<>(names).size()!=width||names.stream().anyMatch(name->name==null||name.isBlank())||model.source()>=width||model.target()>=width||model.paths().isEmpty())throw new IllegalArgumentException("Process names, source/outcome or paths are unavailable.");Set<Integer> endogenous=new HashSet<>(),nodes=new HashSet<>();Set<String> edges=new HashSet<>();Map<Integer,List<Path>> children=new TreeMap<>();Map<Integer,LinkedHashMap<String,Monomial>> equations=new TreeMap<>();
            for(var path:model.paths()){if(path.source()>=width||path.target()>=width||!edges.add(path.source()+":"+path.target()))throw new IllegalArgumentException("Process paths must be unique and use available columns.");nodes.add(path.source());nodes.add(path.target());endogenous.add(path.target());used.add(path.source());used.add(path.target());children.computeIfAbsent(path.source(),key->new ArrayList<>()).add(path);for(int moderator:path.moderators()){if(moderator>=width||moderator==model.source()||moderator==model.target())throw new IllegalArgumentException("Process moderators must be external to the focal source/outcome.");moderators.add(moderator);used.add(moderator);}var terms=equations.computeIfAbsent(path.target(),key->new LinkedHashMap<>());int[] variables=new int[path.moderators.length+1];variables[0]=path.source();System.arraycopy(path.moderators,0,variables,1,path.moderators.length);for(int subset=1;subset<(1<<variables.length);subset++){int[] columns=new int[Integer.bitCount(subset)];for(int j=0,position=0;j<variables.length;j++)if((subset&(1<<j))!=0)columns[position++]=variables[j];Arrays.sort(columns);terms.putIfAbsent(Arrays.toString(columns),new Monomial(columns));}}
            if(endogenous.contains(model.source()))throw new IllegalArgumentException("The focal process source must be exogenous.");for(int moderator:moderators)if(endogenous.contains(moderator))throw new IllegalArgumentException("This conditional process engine requires exogenous moderators; endogenous interaction derivatives need a separate specification.");Set<Integer> controls=new HashSet<>();for(int control:model.controls()){if(control<0||control>=width||!controls.add(control)||nodes.contains(control)||moderators.contains(control))throw new IllegalArgumentException("Process controls must be unique columns separate from modeled variables and moderators.");if(options.considerControls()){used.add(control);for(var terms:equations.values())terms.putIfAbsent("["+control+"]",new Monomial(new int[]{control}));}}
            Map<Integer,Integer> indegree=new HashMap<>();for(int node:nodes)indegree.put(node,0);for(var path:model.paths())indegree.merge(path.target(),1,Integer::sum);ArrayDeque<Integer> queue=new ArrayDeque<>();for(int node:nodes)if(indegree.get(node)==0)queue.add(node);int visited=0;while(!queue.isEmpty()){int node=queue.remove();visited++;for(var path:children.getOrDefault(node,List.of()))if(indegree.merge(path.target(),-1,Integer::sum)==0)queue.add(path.target());}if(visited!=nodes.size())throw new IllegalArgumentException("Process paths must be acyclic.");if(nodes.size()>100||model.paths().size()>500)throw new IllegalArgumentException("Process graph exceeds the current size limit.");enumerate(model.source(),model.target(),children,new ArrayList<>());if(routes.isEmpty())throw new IllegalArgumentException("No directed route connects the focal source to its outcome.");definitions=equations.entrySet().stream().map(entry->new Definition(entry.getKey(),List.copyOf(entry.getValue().values()))).toList();if(definitions.stream().anyMatch(definition->definition.predictors().size()>200))throw new IllegalArgumentException("Process equation exceeds the current predictor limit.");
            probes=suppliedProbes.isEmpty()?List.of(new Probe("Moderator means",Map.of())):List.copyOf(suppliedProbes);Set<String> probeNames=new HashSet<>();if(probes.size()>100)throw new IllegalArgumentException("Use at most 100 process probe conditions.");for(var probe:probes){if(!probeNames.add(probe.name())||!moderators.containsAll(probe.values().keySet()))throw new IllegalArgumentException("Probe names must be unique and values must refer to configured moderators.");}
        }
        private void enumerate(int source,int target,Map<Integer,List<Path>> children,List<Path> prefix){Matrices.interrupted();if(source==target){routes.add(List.copyOf(prefix));if(routes.size()>10000)throw new IllegalArgumentException("Too many process routes; simplify the model.");return;}for(var path:children.getOrDefault(source,List.of())){prefix.add(path);enumerate(path.target(),target,children,prefix);prefix.remove(prefix.size()-1);}}
        State estimate(double[][] data,boolean detailed){
            int n=data.length;if(Matrices.width(data,3)!=width)throw new IllegalArgumentException("Process data width differs from the model.");long predictors=definitions.stream().mapToLong(definition->definition.predictors().size()).sum();if(n*predictors>20000000L)throw new IllegalArgumentException("Process design exceeds the current memory limit.");double[] means=new double[width],centers=new double[width],scales=new double[width];Arrays.fill(means,Double.NaN);Arrays.fill(centers,Double.NaN);Arrays.fill(scales,Double.NaN);for(int column:used){Matrices.interrupted();double mean=0;for(int i=0;i<n;i++)mean+=(data[i][column]-mean)/(i+1);means[column]=mean;centers[column]=options.metric()==Metric.UNSTANDARDIZED?0:mean;double variance=0;for(double[] row:data)variance+=Math.pow(row[column]-mean,2)/n;scales[column]=options.metric()==Metric.STANDARDIZED?Math.sqrt(variance):1;if(!Double.isFinite(mean)||!(scales[column]>0)||!Double.isFinite(scales[column]))throw new IllegalArgumentException("Constant or unscalable standardized process variable: "+names.get(column));}
            List<Equation> fitted=new ArrayList<>();Map<Integer,Equation> byResponse=new HashMap<>();for(var definition:definitions){Matrices.interrupted();int q=definition.predictors().size();if(n<=q+1)throw new IllegalArgumentException("Process equation has too few observations for its predictors.");double[][] x=new double[n][q];double[] y=new double[n];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();y[i]=(data[i][definition.response()]-centers[definition.response()])/scales[definition.response()];for(int j=0;j<q;j++){double value=1;for(int column:definition.predictors().get(j).columns)value*=(data[i][column]-centers[column])/scales[column];x[i][j]=value;}}var inference=detailed?RobustRegression.fit(x,y,options.covariance(),options.confidence()):null;var ordinary=detailed?inference.ordinary():OlsRegression.fit(x,y);var equation=new Equation(definition.response(),definition.predictors(),ordinary,inference);fitted.add(equation);byResponse.put(equation.response(),equation);}
            List<Probe> resolved=new ArrayList<>();List<ConditionalPath> conditional=new ArrayList<>();List<Effect> effects=new ArrayList<>();for(var requested:probes){Map<Integer,Double> rawValues=new LinkedHashMap<>();for(int moderator:moderators)rawValues.put(moderator,requested.values().getOrDefault(moderator,means[moderator]));var probe=new Probe(requested.name(),rawValues);resolved.add(probe);double[] values=new double[width];for(int column:used)values[column]=(rawValues.getOrDefault(column,means[column])-centers[column])/scales[column];Map<String,Double> pathEffects=new HashMap<>();for(var path:model.paths()){var equation=byResponse.get(path.target());double[] contrast=contrast(equation,path.source(),-1,values);double value=dot(contrast,equation.ordinary().coefficients());pathEffects.put(path.source()+":"+path.target(),value);if(detailed)conditional.add(new ConditionalPath(probe.name(),path.source(),path.target(),inference(equation,contrast,value,options)));}double direct=0,indirect=0;Map<Integer,Double> derivatives=new TreeMap<>();for(int moderator:moderators)derivatives.put(moderator,0.0);for(var route:routes){double value=1;for(var path:route)value*=pathEffects.get(path.source()+":"+path.target());if(route.size()==1)direct+=value;else{indirect+=value;String label=routeLabel(route,names);effects.add(new Effect(probe.name(),"Specific indirect",label,value));for(int moderator:moderators){double derivative=0;for(int j=0;j<route.size();j++){var path=route.get(j);var equation=byResponse.get(path.target());double term=dot(contrast(equation,path.source(),moderator,values),equation.ordinary().coefficients())/scales[moderator];for(int other=0;other<route.size();other++)if(other!=j){var edge=route.get(other);term*=pathEffects.get(edge.source()+":"+edge.target());}derivative+=term;}derivatives.merge(moderator,derivative,Double::sum);}}}effects.add(new Effect(probe.name(),"Direct",names.get(model.source())+" → "+names.get(model.target()),direct));effects.add(new Effect(probe.name(),"Total indirect",names.get(model.source())+" → "+names.get(model.target()),indirect));effects.add(new Effect(probe.name(),"Total",names.get(model.source())+" → "+names.get(model.target()),direct+indirect));for(var entry:derivatives.entrySet())effects.add(new Effect(probe.name(),"Conditional indirect derivative","Per raw unit of "+names.get(entry.getKey()),entry.getValue()));}
            if(effects.stream().anyMatch(effect->!Double.isFinite(effect.value())))throw new IllegalArgumentException("Conditional process effect exceeded finite range.");return new State(means,centers,scales,fitted,resolved,conditional,effects);
        }
        Fit describe(State state,int n){List<String> warnings=new ArrayList<>();warnings.add("Observed-variable linear path models; exogenous moderators only. Product terms include all lower-order main/interactions. Controls enter every response equation when enabled.");warnings.add("Probe values are in original units. Centering/scaling is re-estimated within each resample; frozen original-unit probe conditions are evaluated using that resample's transformation. Non-probed variables in local path contrasts are held at their sample means.");warnings.add("Indirect effects and their moderator derivatives require paired bootstrap uncertainty; equation coefficient covariances do not provide a cross-equation indirect-effect test. A moderator derivative need not be a constant index when several paths are moderated.");warnings.add("Fitted conditional associations do not establish causal mediation. Check confounding, functional form, measurement, independence and missing-data assumptions. No multiplicity adjustment is applied.");for(var equation:state.equations())if(equation.inference()!=null)warnings.addAll(equation.inference().warnings().stream().map(message->names.get(equation.response())+": "+message).toList());return new Fit(model,options,n,names,state.means(),state.centers(),state.scales(),state.probes(),state.equations(),state.paths(),state.effects(),warnings);}
        double[] vector(State state){List<Double> values=new ArrayList<>();for(var equation:state.equations())for(double coefficient:equation.ordinary().coefficients())values.add(coefficient);for(var effect:state.effects())values.add(effect.value());return values.stream().mapToDouble(Double::doubleValue).toArray();}
        List<Bootstrap.Parameter> parameters(State state){List<Bootstrap.Parameter> parameters=new ArrayList<>();for(var equation:state.equations()){parameters.add(new Bootstrap.Parameter("Process coefficient",equation.response(),-1,0,names.get(equation.response())+": Intercept"));for(int j=0;j<equation.predictors().size();j++)parameters.add(new Bootstrap.Parameter("Process coefficient",equation.response(),-1,j+1,names.get(equation.response())+": "+monomialLabel(equation.predictors().get(j),names)));}for(int j=0;j<state.effects().size();j++){var effect=state.effects().get(j);parameters.add(new Bootstrap.Parameter(effect.family(),model.source(),model.target(),j,effect.probe()+": "+effect.label()));}return parameters;}
    }
    public static void validate(int columns,List<String> names,Model model,Options options,List<Probe> probes){new Work(columns,names,model,options,probes);}
    public static Fit fit(double[][] data,List<String> names,Model model,Options options,List<Probe> probes){var work=new Work(Matrices.width(data,3),names,model,options,probes);return work.describe(work.estimate(data,true),data.length);}
    /** Fitted structural conditional mean in raw outcome units, with controls/other roots held at means. */
    public static double predict(Fit fit,Probe probe,double sourceValue){
        if(!Double.isFinite(sourceValue))throw new IllegalArgumentException("Use a finite raw source value.");Set<Integer> modifiers=new HashSet<>();for(var path:fit.model().paths())for(int column:path.moderators())modifiers.add(column);if(!modifiers.containsAll(probe.values().keySet()))throw new IllegalArgumentException("Prediction probe refers to an unconfigured moderator.");double[] values=new double[fit.names().size()];for(int column=0;column<values.length;column++)values[column]=(fit.means[column]-fit.centers[column])/fit.scales[column];for(var entry:probe.values().entrySet())values[entry.getKey()]=(entry.getValue()-fit.centers[entry.getKey()])/fit.scales[entry.getKey()];values[fit.model().source()]=(sourceValue-fit.centers[fit.model().source()])/fit.scales[fit.model().source()];Set<Integer> pending=new HashSet<>();for(var equation:fit.equations())pending.add(equation.response());while(!pending.isEmpty()){Matrices.interrupted();boolean changed=false;for(var equation:fit.equations())if(pending.contains(equation.response())&&equation.predictors().stream().flatMapToInt(term->Arrays.stream(term.columns())).noneMatch(pending::contains)){double[] coefficients=equation.ordinary().coefficients();double value=coefficients[0];for(int j=0;j<equation.predictors().size();j++){double product=coefficients[j+1];for(int column:equation.predictors().get(j).columns())product*=values[column];value+=product;}if(!Double.isFinite(value))throw new IllegalArgumentException("Conditional mean exceeded finite range.");values[equation.response()]=value;pending.remove(equation.response());changed=true;}if(!changed)throw new IllegalArgumentException("Cannot order process prediction equations.");}double result=fit.centers[fit.model().target()]+fit.scales[fit.model().target()]*values[fit.model().target()];if(!Double.isFinite(result))throw new IllegalArgumentException("Conditional outcome exceeded finite range.");return result;
    }
    public static BootstrapResult bootstrap(double[][] data,List<String> names,Model model,Options options,List<Probe> probes,Bootstrap.Options bootstrap,IntConsumer progress){var work=new Work(Matrices.width(data,3),names,model,options,probes);var state=work.estimate(data,true);var point=work.describe(state,data.length);var frozen=new Work(data[0].length,names,model,options,state.probes());var inference=Resampling.run(data,work.parameters(state),work.vector(state),bootstrap,(sample,rows)->frozen.vector(frozen.estimate(sample,false)),progress,"Observed-variable conditional process","The same iid row draw is used for every equation; original-unit probe values remain fixed; no factor sign ambiguity");Set<String> fixed=new HashSet<>();boolean direct=work.routes.stream().anyMatch(route->route.size()==1),indirect=work.routes.stream().anyMatch(route->route.size()>1);for(var effect:state.effects()){boolean identity=effect.family().equals("Direct")&&!direct||effect.family().equals("Total indirect")&&!indirect;if(effect.family().equals("Conditional indirect derivative"))for(int moderator:work.moderators)if(effect.label().equals("Per raw unit of "+names.get(moderator)))identity=work.routes.stream().filter(route->route.size()>1).noneMatch(route->route.stream().anyMatch(path->Arrays.stream(path.moderators()).anyMatch(column->column==moderator)));if(identity)fixed.add(effect.family()+"|"+effect.probe()+": "+effect.label());}Set<Integer> centeredIntercepts=new HashSet<>();if(options.metric()!=Metric.UNSTANDARDIZED)for(var equation:state.equations())if(equation.predictors().stream().allMatch(term->term.columns().length==1))centeredIntercepts.add(equation.response());if(!fixed.isEmpty()||!centeredIntercepts.isEmpty())inference=Resampling.suppressTests(inference,parameter->fixed.contains(parameter.family()+"|"+parameter.label())||parameter.family().equals("Process coefficient")&&parameter.column()==0&&centeredIntercepts.contains(parameter.source()),"Ratio tests suppressed for structurally absent effects and definitionally zero centered linear intercepts. Any degenerate zero intervals are identities, not evidence from a sampling test.");return new BootstrapResult(point,inference);}
    private static String monomialLabel(Monomial term,List<String> names){return String.join(" × ",Arrays.stream(term.columns()).mapToObj(names::get).toList());}
    private static String routeLabel(List<Path> route,List<String> names){List<String> values=new ArrayList<>();values.add(names.get(route.get(0).source()));for(var path:route)values.add(names.get(path.target()));return String.join(" → ",values);}
    private static double[] contrast(Equation equation,int source,int second,double[] values){double[] result=new double[equation.predictors().size()+1];if(source==second)return result;for(int j=0;j<equation.predictors().size();j++){int[] columns=equation.predictors().get(j).columns;if(Arrays.stream(columns).noneMatch(column->column==source)||second>=0&&Arrays.stream(columns).noneMatch(column->column==second))continue;double value=1;for(int column:columns)if(column!=source&&column!=second)value*=values[column];result[j+1]=value;}return result;}
    private static double dot(double[] a,double[] b){double value=0;for(int j=0;j<a.length;j++)value+=a[j]*b[j];if(!Double.isFinite(value))throw new IllegalArgumentException("Process contrast exceeded finite range.");return value;}
    private static Inference.Term inference(Equation equation,double[] contrast,double value,Options options){double[][] covariance=equation.inference().coefficientCovariance();double variance=0,absolute=0;for(int j=0;j<contrast.length;j++)for(int k=0;k<contrast.length;k++){double term=contrast[j]*covariance[j][k]*contrast[k];variance+=term;absolute+=Math.abs(term);}if(!Double.isFinite(variance)||variance<-1e-10*Math.max(1,absolute))throw new IllegalArgumentException("Process conditional covariance is invalid.");double se=Math.sqrt(Math.max(0,variance)),statistic=Inference.ratio(value,se),p,critical;if(options.covariance()==RobustRegression.Covariance.CLASSICAL){var distribution=new TDistribution(equation.ordinary().residualDegreesOfFreedom());p=Double.isNaN(statistic)?Double.NaN:2*distribution.cumulativeProbability(-Math.abs(statistic));critical=distribution.inverseCumulativeProbability((1+options.confidence())/2);}else{p=Inference.normalTwoSided(statistic);critical=new NormalDistribution().inverseCumulativeProbability((1+options.confidence())/2);}return new Inference.Term(value,se,statistic,p,value-critical*se,value+critical*se);}
}
